function validate([arr]) {
  if (arr.length < 1 || arr.length > 10000) return 'arr needs 1 to 10,000 values.';
  if (arr.some(v => v < 0 || v > 9)) return 'Each value is a digit from 0 to 9.';
  return null;
}

