function duplicateZeros(arr) {
  const n = arr.length;
  let zeros = 0;
  for (const value of arr) {
    if (value === 0) zeros++;
  }
  let read = n - 1;
  let write = n + zeros - 1;
  while (read < write) {
    if (write < n) {
      arr[write] = arr[read];
    }
    write--;
    if (arr[read] === 0) {
      if (write < n) {
        arr[write] = 0;
      }
      write--;
    }
    read--;
  }
}

