function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const zeroChance = rand() * 0.6;
  return [Array.from({ length: n }, () => rand() < zeroChance ? 0 : 1 + Math.floor(rand() * 9))];
}
